function defaultDashboards(){return [{id:uid(),name:'Mein Überblick',widgets:[{type:'overview',title:'Dein Monat in Zahlen',width:'fullwidth'},{type:'categories',title:'Wohin fließt dein Geld?',style:'donut'},{type:'trend',title:'Einnahmen & Ausgaben',style:'bar',range:6},{type:'budgets',title:'Dein Budget im Blick'},{type:'insights',title:'Was du wissen solltest'}].map(w=>({id:uid(),width:'half',metric:'expenses',palette:'violet',category:'all',range:6,...w}))}]}
function normalizeExtras(src){let dashboards=Array.isArray(src.dashboards)?src.dashboards.slice(0,20).filter(d=>d&&typeof d.name==='string').map(d=>({id:String(d.id||uid()),name:d.name.slice(0,60),widgets:(Array.isArray(d.widgets)?d.widgets:[]).slice(0,30).filter(w=>w&&Object.hasOwn(WIDGET_TYPES,w.type)).map(w=>({id:String(w.id||uid()),type:w.type,title:String(w.title||WIDGET_TYPES[w.type]).slice(0,80),width:['half','third','fullwidth'].includes(w.width)?w.width:'half',style:['bar','line','donut'].includes(w.style)?w.style:'bar',metric:['income','expenses','balance'].includes(w.metric)?w.metric:'expenses',palette:Object.hasOwn(PALETTES,w.palette)?w.palette:'violet',category:String(w.category||'all'),range:[3,6,12].includes(Number(w.range))?Number(w.range):6}))})):defaultDashboards();if(!dashboards.length)dashboards=defaultDashboards();const goals=Array.isArray(src.goals)?src.goals.slice(0,100).filter(g=>g&&typeof g.name==='string'&&Number.isFinite(Number(g.target))&&Number(g.target)>0).map(g=>({id:String(g.id||uid()),name:g.name.slice(0,80),target:Number(g.target),saved:Number.isFinite(Number(g.saved))?Math.max(0,Number(g.saved)):0,date:validDate(g.date)?g.date:''})):[];return{dashboards,activeDashboard:dashboards.some(d=>d.id===src.activeDashboard)?src.activeDashboard:dashboards[0].id,goals}}
function ensureExtras(){if(!state.dashboards?.length)Object.assign(state,normalizeExtras(state));if(!state.goals)state.goals=[];if(!state.dashboards.some(d=>d.id===state.activeDashboard))state.activeDashboard=state.dashboards[0].id}
function activeDashboard(){ensureExtras();return state.dashboards.find(d=>d.id===state.activeDashboard)}
function renderWorkspace(){ensureExtras();renderBalancePanel();renderCustomDashboard();renderAnalysis();renderGoals()}
function renderCustomDashboard(){const d=activeDashboard();$('dashboardWorkspace').innerHTML=`<div class="dash-heading"><div class="dash-tabs" role="group" aria-label="Dashboards">${state.dashboards.map(x=>`<button class="btn ${x.id===d.id?'active':''}" data-dash="${escapeHTML(x.id)}">${escapeHTML(x.name)}</button>`).join('')}</div><div class="action-group"><button class="btn small" data-work="newDash">＋ Dashboard</button><button class="btn small" data-work="editDash">${dashboardEditing?'✓ Fertig':'⚙ Anpassen'}</button><button class="btn small" data-work="print">Drucken / PDF</button></div></div>${dashboardEditing?`<div class="edit-note between"><span>Diagramme frei zusammenstellen. Mit den Pfeilen änderst du die Reihenfolge.</span><span class="action-group"><button class="btn small" data-work="renameDash">Umbenennen</button><button class="btn small" data-work="copyDash">Duplizieren</button><button class="btn small danger" data-work="deleteDash" ${state.dashboards.length===1?'disabled':''}>Löschen</button></span></div>`:''}<div class="widget-grid">${d.widgets.map((w,i)=>`<article class="panel widget ${w.width==='fullwidth'?'fullwidth':w.width==='third'?'third':''}"><div class="widget-head"><div><div class="tiny-label">${escapeHTML(WIDGET_TYPES[w.type])}</div><h2>${escapeHTML(w.title)}</h2><div class="widget-sub">${widgetPeriod(w)}</div></div>${dashboardEditing?`<div class="widget-tools"><button class="icon-btn" data-widget="${escapeHTML(w.id)}" data-op="up" aria-label="Widget nach vorne" ${i===0?'disabled':''}>←</button><button class="icon-btn" data-widget="${escapeHTML(w.id)}" data-op="down" aria-label="Widget nach hinten" ${i===d.widgets.length-1?'disabled':''}>→</button><button class="icon-btn" data-widget="${escapeHTML(w.id)}" data-op="edit">Bearbeiten</button><button class="icon-btn" data-widget="${escapeHTML(w.id)}" data-op="delete" aria-label="Widget entfernen">✕</button></div>`:''}</div><div class="widget-body">${widgetContent(w)}</div></article>`).join('')}${dashboardEditing||!d.widgets.length?'<button class="panel widget" style="min-height:180px;color:var(--brand);border-style:dashed" data-work="newWidget">＋ Diagramm oder Widget hinzufügen</button>':''}</div>`}
function widgetPeriod(w){return w.type==='trend'?`${w.range} Monate bis ${escapeHTML(prettyMonth(currentMonth()))}`:w.type==='goals'?'Manuell gepflegte Rücklagen':escapeHTML(periodInfo().label)}
function widgetTransactions(w,month){return monthTransactions(month).filter(t=>w.category==='all'||t.categoryId===w.category)}
function chartTable(rows){return `<details class="chart-data"><summary>Werte als Tabelle anzeigen</summary><div class="table-scroll"><table class="table"><thead><tr><th>Zeitraum / Kategorie</th><th class="right">Betrag</th></tr></thead><tbody>${rows.map(([label,n])=>`<tr><td>${escapeHTML(label)}</td><td class="money">${eur(n)}</td></tr>`).join('')}</tbody></table></div></details>`}
function widgetContent(w){const arr=widgetTransactions(w),s=sums(arr),colors=PALETTES[w.palette]||PALETTES.violet;if(w.type==='overview')return `<div class="grid kpis">${kpi('Einnahmen',s.income,'income','Im gewählten Zeitraum')+kpi('Ausgaben',s.expenses,'expense','Im gewählten Zeitraum')+kpi(periodResult(),s.balance,'balance','Einnahmen minus Ausgaben')+kpi('Sparquote',s.rate,'rate',s.income?'Anteil vom Einkommen':'Ohne Einkommen nicht aussagekräftig')}</div>`;if(w.type==='budgets')return $('budgetPreview').innerHTML;if(w.type==='insights')return $('insights').innerHTML;if(w.type==='recent')return $('recentList').innerHTML;if(w.type==='goals')return state.goals.length?state.goals.map(g=>budgetRow(g.name,g.saved,g.target)).join(''):'<div class="widget-empty">Lege unter „Sparziele“ dein erstes Ziel an.</div>';if(w.type==='categories'){const map=new Map();for(const t of arr){if(w.metric==='expenses'&&t.amount>=0||w.metric==='income'&&t.amount<=0)continue;const name=catLabel(t);map.set(name,(map.get(name)||0)+(w.metric==='expenses'?-t.amount:t.amount))}let rows=[...map].sort((a,b)=>b[1]-a[1]);if(!rows.length)return '<div class="widget-empty">Keine passenden Buchungen in diesem Monat.</div>';if(rows.length>8)rows=[...rows.slice(0,7),['Weitere Kategorien',rows.slice(7).reduce((sum,r)=>sum+r[1],0)]];const total=rows.reduce((a,r)=>a+r[1],0);if(w.style==='donut'&&w.metric!=='balance'&&total>0){let a=0;const stops=rows.map((r,i)=>{const start=a;a+=r[1]/total*100;return `${colors[i%colors.length]} ${start}% ${a}%`});return `<div class="chart-wrap"><div class="donut" role="img" aria-label="Kategorienverteilung; Werte in der folgenden Legende" style="background:conic-gradient(${stops.join(',')})"></div><div class="legend">${rows.map((r,i)=>`<div class="legend-item"><span class="dot" style="background:${colors[i%colors.length]}"></span><span>${escapeHTML(r[0])}</span><span class="value">${eur(r[1])}</span></div>`).join('')}</div></div>`}const max=Math.max(1,...rows.map(r=>Math.abs(r[1])));return `<div class="chart-bars">${rows.map((r,i)=>`<div><div class="between"><span>${escapeHTML(r[0])}</span><b>${eur(r[1])}</b></div><div class="chart-bar-track"><span style="width:${Math.abs(r[1])/max*100}%;background:${r[1]<0?'var(--red)':colors[i%colors.length]}"></span></div></div>`).join('')}</div>`}
if(w.type==='trend'){const months=previousMonths(currentMonth(),w.range);const rows=months.map(m=>[prettyMonth(m),sums(widgetTransactions(w,m))[w.metric]]);return plot(rows,w.style,colors[0])+chartTable(rows)}if(w.type==='daily'){const p=periodInfo();let rows;if(p.kind==='month')rows=Array.from({length:p.days},(_,i)=>{const date=p.key+'-'+String(i+1).padStart(2,'0');return[String(i+1),sums(arr.filter(t=>t.date===date))[w.metric]]});else if(p.days<=62)rows=Array.from({length:p.days},(_,i)=>{const date=shiftDate(p.from,i);return[date.slice(8)+'.'+date.slice(5,7)+'.',sums(arr.filter(t=>t.date===date))[w.metric]]});else rows=p.months.map(m=>[prettyMonth(m),sums(arr.filter(t=>t.date.startsWith(m)))[w.metric]]);return plot(rows,w.style,colors[0])+chartTable(rows)}return ''}
function plot(rows,style,color){if(!rows.some(r=>r[1]))return '<div class="widget-empty">Noch keine Werte für dieses Diagramm.</div>';const W=680,H=240,L=65,R=15,T=15,B=38,low=Math.min(0,...rows.map(r=>r[1])),high=Math.max(0,...rows.map(r=>r[1])),span=high-low||1,x=i=>L+(i+.5)*(W-L-R)/rows.length,y=n=>T+(high-n)/span*(H-T-B),zero=y(0),step=(W-L-R)/rows.length;let svg=`<svg viewBox="0 0 ${W} ${H}" role="img" aria-label="Diagramm mit Werten in der aufklappbaren Tabelle">`;for(let i=0;i<=4;i++){const v=low+span*i/4,py=y(v);svg+=`<line x1="${L}" y1="${py}" x2="${W-R}" y2="${py}" stroke="var(--line)"/><text x="${L-8}" y="${py+4}" text-anchor="end" font-size="10" fill="var(--muted)">${Math.round(v).toLocaleString('de-DE')}</text>`}svg+=`<line x1="${L}" y1="${zero}" x2="${W-R}" y2="${zero}" stroke="var(--muted)"/>`;if(style==='line')svg+=`<polyline points="${rows.map((r,i)=>`${x(i)},${y(r[1])}`).join(' ')}" fill="none" stroke="${color}" stroke-width="3" stroke-linejoin="round"/>`;rows.forEach((r,i)=>{const title=`${escapeHTML(r[0])}: ${eur(r[1])}`;svg+=style==='line'?`<circle cx="${x(i)}" cy="${y(r[1])}" r="4" fill="${color}"><title>${title}</title></circle>`:`<rect x="${x(i)-step*.3}" y="${Math.min(zero,y(r[1]))}" width="${step*.6}" height="${Math.max(1,Math.abs(y(r[1])-zero))}" rx="3" fill="${r[1]<0?'#cd7f70':color}"><title>${title}</title></rect>`;if(rows.length<=12||i%5===0)svg+=`<text x="${x(i)}" y="${H-12}" text-anchor="middle" font-size="10" fill="var(--muted)">${escapeHTML(rows.length>12?r[0]:r[0].slice(0,3))}</text>`});return svg+'</svg>'}
