function setupDeveloperSupport(){const button=$('supportDeveloperBtn');if(!SUPPORT_URL)return;button.disabled=false;$('supportStatus').textContent='Öffnet die Unterstützungsseite in deinem Browser';button.addEventListener('click',()=>{if(typeof nativeSend==='function'&&nativeSend({action:'support'}))return;window.open(SUPPORT_URL,'_blank','noopener,noreferrer')})}

